import Foundation
import XCTest
import PhotoCraftCore
@testable import PhotoCraftImaging

final class PSDLayerLinksTests:XCTestCase{
  func fixture(_ depth:PixelDepth = .u8,group:Bool=false)throws->CraftDocument{var d=try CraftDocument(width:20,height:16,depth:depth),a=Layer(name:"A",content:.raster(try Surface(width:3,height:2,depth:depth,fill:Pixel(1,0,0)))),b=Layer(name:"B",content:.raster(try Surface(width:4,height:3,depth:depth,fill:Pixel(0,0,1))));a.x=2;a.y=3;b.x=9;b.y=6;d.layers=[a,b];d.activeLayerID=a.id;if group{try Command.groupLayers([a.id],"Group").apply(to:&d)};let ids=d.layers.filter{$0.name != "A" || !group}.map(\.id);try Command.layerLinks(.link(ids)).apply(to:&d);try Command.layerLinks(.enabled([b.id],false)).apply(to:&d);return d}
  func resources(_ bytes:Data)throws->[PSDImageResources.Block]{var r=PSDReader(data:bytes);_=try r.bytes(26);_=try r.bytes(r.u32());return try PSDImageResources.blocks(r.bytes(r.u32()))}
  func testPSDPSBThreeDepthsPreserveLinksDisabledAndPhysicalGroupRecords()throws{
    for depth in PixelDepth.allCases{for format:PSDFileFormat in [.psd,.psb]{let d=try fixture(depth,group:true),bytes=try PSDCodec.writeRasterLayers(d,format:format),read=try PSDCodec.read(bytes),members=read.layers.filter{$0.linkID != nil};XCTAssertEqual(Set(members.map(\.name)),["Group","B"]);XCTAssertEqual(members[0].linkID,members[1].linkID);XCTAssertEqual(read.layers.first{$0.name=="B"}?.linkDisabled,true);XCTAssertNil(read.layers.first{$0.name=="Group"}?.linkDisabled);XCTAssertNil(read.layers.first{$0.name=="A"}?.linkID);XCTAssertEqual(read.depth,depth);let blocks=try resources(bytes),groups=try XCTUnwrap(blocks.first{$0.id==1026}),flags=try XCTUnwrap(blocks.first{$0.id==1072});XCTAssertEqual(groups.data.count,8);XCTAssertEqual(flags.data.count,4);XCTAssertEqual(groups.data,Data([0,0,0,0,0,1,0,1]));XCTAssertEqual(flags.data,Data([1,1,1,0]));let second=try resources(PSDCodec.writeRasterLayers(read,format:format));XCTAssertEqual(second.first{$0.id==1026}?.raw,groups.raw);XCTAssertEqual(second.first{$0.id==1072}?.raw,flags.raw);if let path=ProcessInfo.processInfo.environment["PHOTATO_TEST_CAPTURE_DIR"]{let dir=URL(fileURLWithPath:path);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);try bytes.write(to:dir.appendingPathComponent("links-\(depth.rawValue).\(format == .psd ? "psd":"psb")"))}}}
  }
  func testNamedResourcesNumericIDsPaddingAndEditsRetainValidProvenance()throws{
    var d=try fixture();let numeric=Data([1,2]);for i in d.layers.indices{d.layers[i].sourceTags=["PhLG":numeric]};func named(_ id:Int,_ payload:Data)->Data{var w=PSDWriter();w.text("8BIM");w.n(id,2);w.n(2,1);w.text("FI");w.n(0x5a,1);w.section(payload);if payload.count%2 != 0{w.n(0,1)};return w.data};let a=named(1026,numeric+numeric),b=named(1072,Data([1,0])),other=PSDImageResources.block(4000,data:Data([4,5,6])),resources=a+other+b,entries=d.layers.map{($0,0)};let output=try PSDLayerLinks.applying(resources,entries:entries);XCTAssertEqual(output,resources);try Command.layerLinks(.enabled([d.layers[1].id],true)).apply(to:&d);let edit=try PSDImageResources.blocks(PSDLayerLinks.applying(resources,entries:d.layers.map{($0,0)}));XCTAssertEqual(edit.first{$0.id==1026}?.raw,a);XCTAssertEqual(edit.first{$0.id==4000}?.raw,other);XCTAssertEqual(edit.first{$0.id==1072}?.data,Data([1,1]));XCTAssertEqual(edit.first{$0.id==1072}?.raw.prefix(10),b.prefix(10));try Command.layerLinks(.unlink([d.layers[0].id])).apply(to:&d);let unlink=try PSDImageResources.blocks(PSDLayerLinks.applying(resources,entries:d.layers.map{($0,0)}));XCTAssertEqual(unlink.first{$0.id==1026}?.data,Data(repeating:0,count:4));XCTAssertEqual(try PSDImageResources.preserved(resources),other);XCTAssertEqual(try PSDImageResources.preserved(resources,preservingLayerLinks:true),resources)
  }
  func testDataAndAtomicFileSerializersUseIdenticalLinkBytes()throws{
    let directory=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true);defer{try? FileManager.default.removeItem(at:directory)};for format:PSDFileFormat in [.psd,.psb]{let d=try fixture(.u16,group:true),bytes=try PSDCodec.writeRasterLayers(d,format:format),url=directory.appendingPathComponent("links.\(format == .psd ? "psd":"psb")");try PSDCodec.writeRasterLayers(d,to:url,format:format);XCTAssertEqual(try Data(contentsOf:url),bytes);XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(d)),d)}
  }
  func testMalformedDuplicateCountsFlagsAndNonzeroDividerFailClosed()throws{
    let good=PSDImageResources.block(1026,data:Data([0,1,0,1])),flags=PSDImageResources.block(1072,data:Data([1,1]));for data in [good+good,flags+flags,PSDImageResources.block(1026,data:Data([0,1])),PSDImageResources.block(1072,data:Data([1])),PSDImageResources.block(1072,data:Data([1,2]))]{XCTAssertThrowsError(try PSDLayerLinks.Input(PSDImageResources.blocks(data),records:2))};var input=try PSDLayerLinks.Input(PSDImageResources.blocks(flags),records:2);var layer=Layer(name:"Plain",content:.raster(try Surface(width:1,height:1)));input.apply(0,to:&layer);XCTAssertNil(layer.linkID);var bytes=try PSDCodec.writeRasterLayers(fixture(group:true));var r=PSDReader(data:bytes);_=try r.bytes(26);_=try r.bytes(r.u32());let count=try r.u32(),start=r.offset,blocks=try PSDImageResources.blocks(r.bytes(count));let groups=try XCTUnwrap(blocks.first{$0.id==1026});let relative=try XCTUnwrap(bytes.range(of:groups.raw,in:start..<start+count));let payload=relative.lowerBound+groups.raw.count-groups.data.count;bytes[payload+1]=1;XCTAssertThrowsError(try PSDCodec.read(bytes))
  }
  func testSmartConversionKeepsOuterRelationshipsAndIsolatedCopiesDoNotBorrowPartners()throws{
    let d=try fixture(),id=d.layers[0].id,partner=d.layers[1].id;var converted=d;try SmartObjectIO.convert(in:d,selected:[id]).apply(to:&converted);let smart=try XCTUnwrap(converted.activeLayerID);XCTAssertEqual(converted.layers.first{$0.id==smart}?.linkID,d.layers[0].linkID);XCTAssertEqual(converted.layers.first{$0.id==partner}?.linkID,d.layers[1].linkID);let one=try LayerDuplication.newDocument(from:d,selected:[id],documentName:"Subset");XCTAssertNil(one.layers[0].linkID);let bytes=try PSDCodec.writeRasterLayers(one);XCTAssertFalse(try resources(bytes).contains{$0.id==1026 || $0.id==1072});XCTAssertEqual(try PSDCodec.read(bytes).layers.count,1)
  }
}
